static void Require(bool condition, const char* message) {
	if (!condition) {
		throw std::runtime_error(message);
	}
}

template <typename Operation>
static void RequireFailure(Operation operation) {
	try {
		operation();
	} catch (const std::runtime_error&) {
		return;
	}

	throw std::runtime_error("missing ScreenProjection input rejection");
}

static std::uint32_t Word(std::span<const std::byte> bytes, std::size_t offset) {
	std::uint32_t result = 0;
	for (std::size_t index = 0; index < 4; ++index) {
		result |= std::to_integer<std::uint32_t>(bytes[offset + index]) << (index * 8);
	}

	return result;
}

